export const getUploadPdfUrl = () => {




  return `/api/uploads`
}

/**
 * @summary Upload a PDF stock report for a depot
 */
export const uploadPdf = async (uploadInput: UploadInput, options?: RequestInit): Promise<Upload> => {
    const formData = new FormData();
formData.append(`depotId`, uploadInput.depotId.toString())
if(uploadInput.stockDate !== undefined) {
 formData.append(`stockDate`, uploadInput.stockDate);
 }
formData.append(`file`, uploadInput.file);

  return customFetch<Upload>(getUploadPdfUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





